var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('keeps the 2-decimal default when an options object omits decimalPlaces', function () {
    assert.strictEqual(bytes.format(1536, {}), '1.5KB');
    assert.strictEqual(bytes.format(1536, { unitSeparator: ' ' }), '1.5 KB');
  });

  it('keeps 2 decimals for fixedDecimals when decimalPlaces is omitted', function () {
    assert.strictEqual(bytes.format(1024, { fixedDecimals: true }), '1.00KB');
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // Negative binary integer with an explicit !!int tag must resolve under
    // the default core schema: the explicit pattern is [-+]?0b[0-1]+, so the
    // sign is allowed.
    assert.strictEqual(load('!!int -0b101'), -5);
    // Same for the explicit plus sign.
    assert.strictEqual(load('!!int +0b11'), 3);
    // Unsigned binary keeps working in both builds.
    assert.strictEqual(load('!!int 0b101'), 5);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('uses the plural form at exactly 1.5x a unit', function () {
    assert.strictEqual(ms(1500, { long: true }), '2 seconds');
    assert.strictEqual(ms(90000, { long: true }), '2 minutes');
    assert.strictEqual(ms(5400000, { long: true }), '2 hours');
    assert.strictEqual(ms(129600000, { long: true }), '2 days');
  });
});
